export function validateCostInputs(raw){const v={...COST_DEFAULTS,...raw};for(const key of Object.keys(COST_DEFAULTS)){if(key==='ddTablet'){v[key]=!!raw.ddTablet;continue;}v[key]=Number(v[key]);if(!Number.isFinite(v[key])||v[key]<0)throw Error('Enter a non-negative number for every assumption.');}if(Math.abs(v.soloShare+v.duoShare+v.familyShare-100)>1e-6)throw Error('The three order-size percentages must add up to 100%.');if([v.ddRate,v.uberRate,v.uberOneShare].some(n=>n>100))throw Error('Percentages cannot exceed 100%.');if(v.returnMinutes>120)throw Error('Use a return-time assumption between 0 and 120 minutes.');if(v.wage>500||v.mileageRate>20||Math.max(v.soloPrice,v.duoPrice,v.familyPrice)>2000||v.uberWeekly>1000||v.uberSetup>10000||Math.max(v.ddDrive,v.uberDirect)>100)throw Error('An assumption is outside this demo’s supported range.');return v;}
export function unionMinutes(intervals){const ordered=intervals.filter(([a,b])=>Number.isFinite(a)&&Number.isFinite(b)&&b>=a).sort((a,b)=>a[0]-b[0]);let start=null,end=null,total=0;for(const [a,b] of ordered){if(start===null){start=a;end=b;}else if(a<=end)end=Math.max(end,b);else{total+=end-start;start=a;end=b;}}if(start!==null)total+=end-start;return total/60000;}
