 const base=[],round=[],validIds=new Set();let trips=0,recordedReturns=0,estimatedReturns=0;const shiftStart=stamp(shift.startedAt),shiftEnd=stamp(shift.endedAt);
 for(const r of candidates){const ds=r.deliveryIds.map(id=>byId.get(id)).filter(d=>d&&owner.get(d.id)===r.id),ends=ds.map(d=>stamp(d.completedAt)).filter(n=>n!==null);if(!ends.length||shiftStart===null||shiftEnd===null)continue;const start=Math.max(stamp(r.startedAt),shiftStart),last=Math.max(...ends),end=Math.min(last,shiftEnd);if(end<start||last>shiftEnd||stamp(r.startedAt)<shiftStart)continue;trips++;ds.forEach(d=>validIds.add(d.id));base.push([start,end]);const returned=stamp(r.returnedAt),recorded=!assumeAllReturns&&returned!==null&&returned>=last&&returned<=shiftEnd;if(recorded)recordedReturns++;else estimatedReturns++;round.push([start,recorded?returned:Math.min(shiftEnd,last+returnMinutes*60000)]);}
