 for(const shift of ss){const timing=shiftDeliveryTime(state,shift,assumptions.returnMinutes,options),day=dayKey(shift.startedAt),dayMs=Date.parse(day+'T12:00:00Z'),spanDays=previousDay===null?1:Math.max(0,(dayMs-previousDay)/86400000),actualMiles=miles(shift),wages=timing.total/60*assumptions.wage,mileage=(actualMiles??0)*assumptions.mileageRate,revenue=timing.orders*average;previousDay=dayMs;rows.push({shiftId:shift.id,date:day,orders:timing.orders,timing,miles:actualMiles,wages,mileage,inhouse:wages+mileage,revenue,ddCommission:revenue*assumptions.ddRate/100,ddEquipment:spanDays/7*ddWeekly,uberCommission:revenue*uberEffectiveRate/100,uberEquipment:spanDays/7*assumptions.uberWeekly,ddDrive:timing.orders*assumptions.ddDrive,uberDirect:timing.orders*assumptions.uberDirect});}
 const sum=key=>rows.reduce((n,r)=>n+(r[key]??0),0),orders=sum('orders'),inhouse=sum('inhouse'),dd=sum('ddCommission')+sum('ddEquipment'),uber=sum('uberCommission')+sum('uberEquipment'),totalMinutes=rows.reduce((n,r)=>n+r.timing.total,0),timedOrders=rows.reduce((n,r)=>n+r.timing.timed,0),trips=rows.reduce((n,r)=>n+r.timing.trips,0),coverageComplete=orders>0&&timedOrders===orders&&rows.every(r=>r.miles!==null),perOrder=orders?inhouse/orders:null;
